#!/usr/bin/env python3
"""Compares terrain generated by a 26.3 dedicated server with and without Oxide.

`run` starts the mod's dev server (`./gradlew runServer`) in its own directory with a
fixed seed, force-loads a square of chunks over RCON, waits until all of them are
loaded, saves, and stops the server. With `--worker`, Oxide generates terrain;
without it, Oxide disables itself and vanilla does.

With `--verify`, vanilla generates terrain and the mod compares the worker's output
for every chunk with it, logging differences (grep the log for "Oxide verify").
Comparing finished worlds with `compare` cannot show Oxide's accuracy on its own:
vanilla's FEATURES step is order dependent, so two vanilla runs already differ.

`compare` reads the overworld region files of two runs and compares every chunk in
the square: block states, biomes and heightmaps.

Example:
    python3 -I tools/server_parity.py run --dir /tmp/vanilla
    python3 -I tools/server_parity.py run --dir /tmp/oxide --worker worker/target/release/oxide-worker
    python3 -I tools/server_parity.py compare /tmp/vanilla /tmp/oxide

Starting the server accepts the Minecraft EULA in the run directory (eula.txt).
"""

import argparse
import gzip
import os
import shutil
import socket
import struct
import subprocess
import sys
import time
import zlib
from pathlib import Path

MOD_DIR = Path(__file__).resolve().parent.parent / "mod"
RCON_PORT = 25575
RCON_PASSWORD = "oxide-parity"


# --- RCON -------------------------------------------------------------------------

class Rcon:
    def __init__(self, port):
        self.sock = socket.create_connection(("127.0.0.1", port), timeout=30)
        self.next_id = 1
        self._send(3, RCON_PASSWORD)

    def _send(self, kind, body):
        request_id = self.next_id
        self.next_id += 1
        data = body.encode("utf-8") + b"\0\0"
        self.sock.sendall(struct.pack("<iii", len(data) + 8, request_id, kind) + data)
        length = struct.unpack("<i", self._read(4))[0]
        payload = self._read(length)
        reply_id = struct.unpack("<i", payload[:4])[0]
        if reply_id == -1:
            raise RuntimeError("RCON authentication failed")
        return payload[8:-2].decode("utf-8", "replace")

    def _read(self, count):
        data = b""
        while len(data) < count:
            chunk = self.sock.recv(count - len(data))
            if not chunk:
                raise RuntimeError("RCON connection closed")
            data += chunk
        return data

    def command(self, text):
        return self._send(2, text)


# --- Region files and NBT ---------------------------------------------------------

def read_nbt(data):
    def payload(tag, pos):
        if tag == 1:
            return struct.unpack_from(">b", data, pos)[0], pos + 1
        if tag == 2:
            return struct.unpack_from(">h", data, pos)[0], pos + 2
        if tag == 3:
            return struct.unpack_from(">i", data, pos)[0], pos + 4
        if tag == 4:
            return struct.unpack_from(">q", data, pos)[0], pos + 8
        if tag == 5:
            return struct.unpack_from(">f", data, pos)[0], pos + 4
        if tag == 6:
            return struct.unpack_from(">d", data, pos)[0], pos + 8
        if tag in (7, 11, 12):
            (count,) = struct.unpack_from(">i", data, pos)
            pos += 4
            fmt, size = {7: ("b", 1), 11: ("i", 4), 12: ("q", 8)}[tag]
            return list(struct.unpack_from(">%d%s" % (count, fmt), data, pos)), pos + count * size
        if tag == 8:
            (length,) = struct.unpack_from(">H", data, pos)
            return data[pos + 2:pos + 2 + length].decode("utf-8", "replace"), pos + 2 + length
        if tag == 9:
            item_tag, count = struct.unpack_from(">bi", data, pos)
            pos += 5
            items = []
            for _ in range(count):
                item, pos = payload(item_tag, pos)
                items.append(item)
            return items, pos
        if tag == 10:
            result = {}
            while True:
                child = data[pos]
                pos += 1
                if child == 0:
                    return result, pos
                (length,) = struct.unpack_from(">H", data, pos)
                name = data[pos + 2:pos + 2 + length].decode("utf-8", "replace")
                result[name], pos = payload(child, pos + 2 + length)
        raise ValueError("unknown NBT tag %d" % tag)

    root_tag = data[0]
    (name_length,) = struct.unpack_from(">H", data, 1)
    return payload(root_tag, 3 + name_length)[0]


def read_chunk(region_dir, chunk_x, chunk_z):
    path = region_dir / ("r.%d.%d.mca" % (chunk_x >> 5, chunk_z >> 5))
    if not path.exists():
        return None
    with open(path, "rb") as file:
        index = (chunk_x & 31) + (chunk_z & 31) * 32
        file.seek(index * 4)
        entry = struct.unpack(">I", file.read(4))[0]
        if entry == 0:
            return None
        file.seek((entry >> 8) * 4096)
        length, compression = struct.unpack(">IB", file.read(5))
        raw = file.read(length - 1)
    if compression == 1:
        raw = gzip.decompress(raw)
    elif compression == 2:
        raw = zlib.decompress(raw)
    elif compression != 3:
        raise ValueError("unsupported chunk compression %d" % compression)
    return read_nbt(raw)


def unpack_palette(container, size):
    palette = container["palette"]
    if len(palette) == 1 or "data" not in container:
        return [0] * size
    bits = max(4 if size == 4096 else 1, (len(palette) - 1).bit_length())
    per_long = 64 // bits
    mask = (1 << bits) - 1
    values = []
    for long_value in container["data"]:
        long_value &= (1 << 64) - 1
        for i in range(per_long):
            if len(values) == size:
                break
            values.append((long_value >> (i * bits)) & mask)
    return values


def state_key(state):
    # 26.3 stores a state without properties as a plain string; NBT lists that mix
    # types wrap non-compound entries as {"": value}.
    if isinstance(state, str):
        return state
    if "" in state:
        return state_key(state[""])
    # 26.3 writes {id, properties}; older versions wrote {Name, Properties}.
    name = state.get("id", state.get("Name"))
    properties = state.get("properties", state.get("Properties", {}))
    return name + "".join("|%s=%s" % item for item in sorted(properties.items()))


def chunk_summary(chunk):
    sections = {}
    for section in chunk.get("sections", []):
        blocks = section.get("block_states")
        biomes = section.get("biomes")
        block_palette = [state_key(state) for state in blocks["palette"]] if blocks else ["minecraft:air"]
        block_ids = unpack_palette(blocks, 4096) if blocks else [0] * 4096
        biome_ids = unpack_palette(biomes, 64) if biomes else [0] * 64
        sections[section["Y"]] = (
            [block_palette[i] for i in block_ids],
            [state_key(biomes["palette"][i]) for i in biome_ids] if biomes else [],
        )
    return {
        "status": chunk.get("Status"),
        "sections": sections,
        "heightmaps": chunk.get("Heightmaps", {}),
    }


def region_dir(run_dir):
    for candidate in ("world/dimensions/minecraft/overworld/region", "world/region"):
        path = Path(run_dir) / candidate
        if path.is_dir():
            return path
    raise FileNotFoundError("no overworld region directory under %s" % run_dir)


# --- Commands ---------------------------------------------------------------------

def square(radius):
    return [(x, z) for z in range(-radius, radius + 1) for x in range(-radius, radius + 1)]


def run(args):
    run_dir = Path(args.dir).resolve()
    run_dir.mkdir(parents=True, exist_ok=True)
    (run_dir / "eula.txt").write_text("eula=true\n")
    mods_dir = run_dir / "mods"
    mods_dir.mkdir(exist_ok=True)
    for jar in args.mods:
        shutil.copy(jar, mods_dir / Path(jar).name)
    (run_dir / "server.properties").write_text("\n".join([
        "level-seed=%d" % args.seed,
        "enable-rcon=true",
        "rcon.port=%d" % RCON_PORT,
        "rcon.password=%s" % RCON_PASSWORD,
        "online-mode=false",
        "view-distance=2",
        "simulation-distance=2",
        "",
    ]))
    command = ["./gradlew", "--no-daemon", "-q", "runServer", "-PrunDir=%s" % run_dir]
    if args.worker:
        command.append("-PoxideWorker=%s" % Path(args.worker).resolve())
    if args.verify:
        command.append("-PoxideVerify")
    if args.no_prefetch:
        command.append("-PoxideNoPrefetch")
    if args.step_timing:
        command.append("-PoxideStepTiming")
    env = dict(os.environ, JAVA_HOME=args.java_home)
    log = open(run_dir / "server-output.log", "w")
    server = subprocess.Popen(command, cwd=MOD_DIR, stdout=log, stderr=subprocess.STDOUT, env=env)
    try:
        rcon = wait_for_rcon(server)
        chunks = square(args.radius)
        start = time.time()
        for dimension in args.dimensions:
            for x0 in range(-args.radius, args.radius + 1, 16):
                for z0 in range(-args.radius, args.radius + 1, 16):
                    x1 = min(x0 + 15, args.radius)
                    z1 = min(z0 + 15, args.radius)
                    print(rcon.command("execute in %s run forceload add %d %d %d %d"
                                       % (dimension, x0 * 16, z0 * 16, x1 * 16, z1 * 16)))
        pending = {(dimension, x, z) for dimension in args.dimensions for x, z in chunks}
        while pending:
            for dimension, chunk_x, chunk_z in list(pending):
                reply = rcon.command("execute in %s if loaded %d 0 %d" % (dimension, chunk_x * 16, chunk_z * 16))
                if "passed" in reply.lower():
                    pending.discard((dimension, chunk_x, chunk_z))
            if pending:
                time.sleep(1)
        print("All %d chunks loaded in %.1f s" % (len(chunks) * len(args.dimensions), time.time() - start))
        print(rcon.command("save-all flush"))
        rcon.command("stop")
        server.wait(timeout=600)
    finally:
        if server.poll() is None:
            server.terminate()
            server.wait(timeout=120)
        log.close()


def wait_for_rcon(server):
    deadline = time.time() + 1200
    while time.time() < deadline:
        if server.poll() is not None:
            raise RuntimeError("server exited early; see server-output.log")
        try:
            return Rcon(RCON_PORT)
        except OSError:
            time.sleep(2)
    raise RuntimeError("server did not open RCON in time")


def compare(args):
    left_dir, right_dir = region_dir(args.left), region_dir(args.right)
    identical = 0
    for chunk_x, chunk_z in square(args.radius):
        left, right = read_chunk(left_dir, chunk_x, chunk_z), read_chunk(right_dir, chunk_x, chunk_z)
        position = "(%d, %d)" % (chunk_x, chunk_z)
        if left is None or right is None:
            print("%s: missing in %s" % (position, "left" if left is None else "right"))
            continue
        a, b = chunk_summary(left), chunk_summary(right)
        problems = []
        if a["status"] != b["status"]:
            problems.append("status %s vs %s" % (a["status"], b["status"]))
        for section_y in sorted(set(a["sections"]) | set(b["sections"])):
            sa, sb = a["sections"].get(section_y), b["sections"].get(section_y)
            if sa is None or sb is None:
                problems.append("section %d missing on one side" % section_y)
                continue
            different = sum(1 for p, q in zip(sa[0], sb[0]) if p != q)
            if different:
                problems.append("section %d: %d blocks differ" % (section_y, different))
            if sa[1] != sb[1]:
                problems.append("section %d: biomes differ" % section_y)
        for name in sorted(set(a["heightmaps"]) | set(b["heightmaps"])):
            if a["heightmaps"].get(name) != b["heightmaps"].get(name):
                problems.append("heightmap %s differs" % name)
        if problems:
            print("%s: %s" % (position, "; ".join(problems[:6])))
        else:
            identical += 1
    total = len(square(args.radius))
    print("%d/%d chunks identical" % (identical, total))
    return 0 if identical == total else 1


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    commands = parser.add_subparsers(dest="command", required=True)
    run_parser = commands.add_parser("run")
    run_parser.add_argument("--dir", required=True)
    run_parser.add_argument("--worker")
    run_parser.add_argument("--seed", type=int, default=13579)
    run_parser.add_argument("--radius", type=int, default=12)
    run_parser.add_argument("--java-home", default="/usr/lib/jvm/java-25-openjdk-amd64")
    run_parser.add_argument("--verify", action="store_true",
                            help="vanilla generates terrain; the mod compares the worker's output with it")
    run_parser.add_argument("--dimensions", nargs="+", default=["minecraft:overworld"])
    run_parser.add_argument("--mods", nargs="*", default=[], help="extra mod jars to install, e.g. C2ME")
    run_parser.add_argument("--no-prefetch", action="store_true", help="turn off Oxide's terrain prefetching")
    run_parser.add_argument("--step-timing", action="store_true", help="log per-step generation time at shutdown")
    compare_parser = commands.add_parser("compare")
    compare_parser.add_argument("left")
    compare_parser.add_argument("right")
    compare_parser.add_argument("--radius", type=int, default=12)
    args = parser.parse_args()
    if args.command == "run":
        run(args)
        return 0
    return compare(args)


if __name__ == "__main__":
    sys.exit(main())
